	private MockHttpServletResponse requestHiddenQuery(boolean conditional) throws Exception {
		return requestConfiguredPath("/query", "menu.item.query.visible=false\n"
				+ "query.feature.result-download-limit.enabled=false\n"
				+ "query.download.default-limit=0\n", conditional);
	}

	private MockHttpServletResponse requestConfiguredPath(String path, String properties) throws Exception {
		return requestConfiguredPath(path, properties, false);
	}

	private MockHttpServletResponse requestConfiguredPath(String path, String properties, boolean conditional)
			throws Exception {
		return requestConfiguredPath(path, properties, conditional, Map.of());
	}

	private MockHttpServletResponse requestConfiguredPath(String path, String properties, boolean conditional,
			Map<String, String> extraRoutes) throws Exception {
		String originalDataDir = System.getProperty(Platform.APPDATA_BASEDIR_PROPERTY);
		System.setProperty(Platform.APPDATA_BASEDIR_PROPERTY, dataBaseDir.toString());
		RecordingRepositoryServlet.invocationCount = 0;
		ProxyRepositoryServlet servlet = new ProxyRepositoryServlet();
		try {
			Path configFile = PlatformFactory.getPlatform()
					.getApplicationDataDir("Workbench")
					.toPath()
					.resolve(Configuration.DIR)
					.resolve("workbench.properties");
			Files.createDirectories(configFile.getParent());
			Files.writeString(configFile, properties);

			Repository repository = mock(Repository.class);
			when(repository.getValueFactory()).thenReturn(SimpleValueFactory.getInstance());
			servlet.setRepository(repository);
			servlet.setRepositoryInfo(new RepositoryInfo());
			servlet.setRepositoryManager(mock(RepositoryManager.class));

			MockServletContext context = new MockServletContext();
			Map<String, String> parameters = new HashMap<>(Map.of(
					"default-command", "/summary",
					"/query", RecordingRepositoryServlet.class.getName(),
					"/namespaces", RecordingRepositoryServlet.class.getName(),
					WorkbenchPolicy.INTERNAL_NAMESPACES_PATH, RecordingRepositoryServlet.class.getName(),
					"transformations", "/transformations"));
			parameters.putAll(extraRoutes);
			ServletConfig config = new TestServletConfig("proxy", context, parameters);
			servlet.init(config);

			MockHttpServletRequest request = new MockHttpServletRequest("GET",
					"/rdf4j-workbench/repositories/example" + path);
			request.setRequestURI("/rdf4j-workbench/repositories/example" + path);
			request.setContextPath("/rdf4j-workbench");
			request.setServletPath("/rdf4j-workbench/repositories/example");
			request.setPathInfo(path);
			request.setScheme("https");
			request.setServerName("example.org");
			request.setServerPort(443);
			if (conditional) {
				request.addHeader("If-Modified-Since", Long.MAX_VALUE);
			}

			MockHttpServletResponse response = new MockHttpServletResponse();
			servlet.service(request, response);
			return response;
		} finally {
			servlet.destroy();
			if (originalDataDir == null) {
				System.clearProperty(Platform.APPDATA_BASEDIR_PROPERTY);
			} else {
				System.setProperty(Platform.APPDATA_BASEDIR_PROPERTY, originalDataDir);
			}
		}
	}

	public static class RecordingRepositoryServlet implements RepositoryServlet {
		private static int invocationCount;

		@Override
		public void init(ServletConfig config) {
		}

		@Override
		public ServletConfig getServletConfig() {
			return null;
		}

		@Override
		public void service(ServletRequest request, ServletResponse response) throws IOException {
			invocationCount++;
			((HttpServletResponse) response).getWriter().write("query servlet reached");
		}

		@Override
		public String getServletInfo() {
			return "recording";
		}

		@Override
		public void destroy() {
		}

		@Override
		public void setRepositoryManager(RepositoryManager manager) {
		}

		@Override
		public void setRepositoryInfo(RepositoryInfo info) {
		}

		@Override
		public void setRepository(Repository repository) {
		}
	}

	public static class CanonicalQueryServlet extends QueryServlet {
		private static int invocationCount;

		@Override
		public void init(ServletConfig config) {
			this.config = config;
			this.cookies = new CookieHandler(config, this);
		}

		@Override
		public void destroy() {
		}

		@Override
		protected void service(WorkbenchRequest request, HttpServletResponse response) {
			invocationCount++;
			response.setStatus(HttpServletResponse.SC_ACCEPTED);
		}
	}
